## Why This Is Asked

Tests knowledge of two classic sorts, practical optimization, and memory trade-offs. A hybrid approach reveals ability to tune algorithms for real data patterns.

## Key Concepts
- Hybrid sorting threshold and when it helps
- Stability via merge vs insertion behavior
- Space usage with a single auxiliary buffer

## Code Example
```javascript
function sortBatch(arr) {
  const n = arr.length;
  const buf = new Array(n);
  function insertionSort(a, left, right) {
    for (let i = left + 1; i <= right; i++) {
      const key = a[i];
      let j = i - 1;
      while (j >= left && a[j] > key) {
        a[j + 1] = a[j];
        j--;
      }
      a[j + 1] = key;
    }
  }
  function merge(left, mid, right) {
    let i = left, j = mid + 1, k = left;
    while (i <= mid && j <= right) {
      if (arr[i] <= arr[j]) buf[k++] = arr[i++];
      else buf[k++] = arr[j++];
    }
    while (i <= mid) buf[k++] = arr[i++];
    while (j <= right) buf[k++] = arr[j++];
    for (let t = left; t <= right; t++) arr[t] = buf[t];
  }
  function sort(l, r) {
    if (l >= r) return;
    if (r - l + 1 <= 16) {
      insertionSort(arr, l, r);
    } else {
      const m = Math.floor((l + r) / 2);
      sort(l, m);
      sort(m + 1, r);
      merge(l, m, r);
    }
  }
  sort(0, n - 1);
}
```

## Why This Question Is Asked
This problem evaluates the ability to extend classic DP patterns (like the staircase problem) with an additional resource dimension, while also testing space optimization skills and recursive thinking via memoization. It distinguishes candidates who understand both bottom-up and top-down approaches, and who reason through edge cases systematically.

## Key Concepts
- DP with an extra budget constraint (two-dimensional state: position + accumulated cost)
- Space optimization using rolling arrays to reduce O(n·B) space to O(B)
- Memoization on composite state (i, b) for the recursive variant
- Correct base case handling when starting from a virtual position before index 0

## Code Example
```javascript
const MOD = 1_000_000_007n;

function countWays(cost, B) {
  const n = cost.length;
  if (n === 0) return 0;

  // bottom-up with rolling arrays
  let prev2 = new Array(B + 1).fill(0);
  let prev1 = new Array(B + 1).fill(0);

  // base: step 0
  if (cost[0] <= B) prev2[cost[0]] = 1;

  // base: step 1
  if (n > 1 && cost[1] <= B) prev1[cost[1]] = 1;

  // step 2 onwards
  for (let i = 2; i < n; i++) {
    const cur = new Array(B + 1).fill(0);
    for (let b = cost[i]; b <= B; b++) {
      cur[b] = (prev1[b - cost[i]] + prev2[b - cost[i]]) % MOD;
    }
    prev2 = prev1;
    prev1 = cur;
  }

  return n === 1 ? prev2[B] : prev1[B];
}

// memoized DFS variant
function countWaysDFS(cost, B) {
  const n = cost.length;
  const memo = new Map();

  function dfs(i, b) {
    if (b < 0) return 0;
    if (i < 0) return b === 0 ? 1 : 0;
    const key = `${i},${b}`;
    if (memo.has(key)) return memo.get(key);
    const result = (dfs(i - 1, b - cost[i]) + dfs(i - 2, b - cost[i])) % MOD;
    memo.set(key, result);
    return result;
  }

  return dfs(n - 1, B);
}
```

## Why This Is Asked
This question tests the ability to extend Dijkstra's algorithm to count shortest paths while handling ties and modular arithmetic—a common pattern in competitive programming and graph algorithms.

## Key Concepts
- Dijkstra's algorithm with path counting augmentation
- Non-negative edge weights, including zero-weight edges
- Modular arithmetic for large path counts and overflow prevention
- Edge case handling: unreachable destinations, multiple optimal paths, zero-weight cycles

## Code Example
```javascript
function countShortestPaths(n, edges, s, t) {
  const MOD = 1e9 + 7;
  const dist = new Array(n).fill(Infinity);
  const ways = new Array(n).fill(0);

  dist[s] = 0;
  ways[s] = 1;

  const pq = new MinPriorityQueue({ priority: x => dist[x] });
  pq.enqueue(s);

  while (!pq.isEmpty()) {
    const u = pq.dequeue().element;

    for (const [v, w] of edges[u]) {
      if (dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
        ways[v] = ways[u];
        pq.enqueue(v);
      } else if (dist[u] + w === dist[v]) {
        ways[v] = (ways[v] + ways[u]) % MOD;
      }
    }
  }

  return { distance: dist[t] === Infinity ? -1 : dist[t], paths: ways[t] };
}
```

## Time & Space Complexity
- **Time**: O((N + M) log N) due to priority queue operations
- **Space**: O(N) for distance and path count arrays

## Why This Is Asked
Explores a practical, augmented Trie approach blending prefix queries with order-statistics, a gap in typical BST/trie questions.

## Key Concepts
- Trie augmentation with endCount and subCount
- Duplicates handled via endCount
- Lexicographic kthWord via endCount before children

## Code Example
```javascript
class Node {
  constructor() {
    this.next = new Map();
    this.end = 0;
    this.sub = 0;
  }
}
class Trie {
  constructor(){ this.root = new Node(); }
  insert(w){ let cur=this.root; cur.sub++; for(const ch of w){ if(!cur.next.has(ch)) cur.next.set(ch,new Node()); cur=cur.next.get(ch); cur.sub++; } cur.end++; }
  delete(w){ let cur=this.root; cur.sub--; for(const ch of w){ cur=cur.next.get(ch); cur.sub--; } cur.end--; }
  countPrefix(p){ let cur=this.root; for(const ch of p){ if(!cur.next.has(ch)) return 0; cur=cur.next.get(ch); } return cur.sub; }
  kthWord(k){ let res=''; let node=this.root; while(true){ if(k <= node.end) return res; k -= node.end; // skip words ending here
      // iterate in lexical order
      const keys = Array.from(node.next.keys()).sort();
      for(const ch of keys){ const child=node.next.get(ch); if(child.sub >= k){ res += ch; node = child; break; } else k -= child.sub; }
    }
  }
}
```

