## Why This Is Asked
Tests ability to derive a recurrence for a simple constraint (no adjacent picks), then implement both top-down memoization and bottom-up tabulation. Requires correct base cases for N=0 and N=1 and translating to iterative state transitions. Follow-up prompts space optimization and practical coding habits.

## Key Concepts
- DP for non-adjacent max sum (House Robber)
- Top-down memoization with base cases
- Bottom-up tabulation
- Space optimization to O(1)

## Code Example
```javascript
function maxNonAdjacent(nums){
  const n = nums.length;
  if (n === 0) return 0;
  const memo = Array(n).fill(-1);
  const solve = i => {
    if (i < 0) return 0;
    if (memo[i] !== -1) return memo[i];
    memo[i] = Math.max(nums[i] + solve(i-2), solve(i-1));
    return memo[i];
  };
  return solve(n-1);
}
function maxNonAdjacentTab(nums){
  const n = nums.length;
  if (n === 0) return 0;
  let prev2 = 0, prev1 = Math.max(0, nums[0]);
  for (let i = 1; i < n; i++){
    const cur = Math.max(prev1, nums[i] + prev2);
    prev2 = prev1;
    prev1 = cur;
  }
  return prev1;
}
```

## Follow-up Questions
- How would you handle negative values or all-negative arrays?
- How would you adapt to a similar constraint with k-adjacent bans (no more than two chosen in any window of size k)?

## Why This Is Asked

Tests multi-state DP design to enforce a direction-run constraint with obstacles, requiring careful state construction and both memoized and tabular implementations.

## Key Concepts

- DP with extra dimensions for last direction and run-length
- Top-down memoization and bottom-up tabulation
- Modulo arithmetic and handling blocked cells; boundary cases when L is large or grid small

## Code Example

```javascript
function countPaths(grid, L){
  const n = grid.length, m = grid[0].length, MOD = 1000000007;
  if(grid[0][0] || grid[n-1][m-1]) return 0;
  const memo = Array.from({length:n},()=>Array.from({length:m},()=>Array.from({length:2},()=>Array(L+1).fill(-1))));
  const endI=n-1, endJ=m-1;
  function dfs(i,j,dir,run){
    if(i===endI && j===endJ) return 1;
    const val = memo[i][j][dir][run];
    if(val!==-1) return val;
    let res = 0;
    // right
    if(j+1<m){
      if((dir===0 && run<L) || dir===1){
        res = (res + dfs(i, j+1, 0, dir===0 ? run+1 : 1)) % MOD;
      }
    }
    // down
    if(i+1<n){
      if((dir===1 && run<L) || dir===0){
        res = (res + dfs(i+1, j, 1, dir===1 ? run+1 : 1)) % MOD;
      }
    }
    memo[i][j][dir][run] = res;
    return res;
  }
  let ans = (dfs(0,0,0,1) + dfs(0,0,1,1)) % MOD;
  return ans;
}
```

## Follow-up Questions
- How would you reduce memory to O(n m)?
- What changes if you allow a diagonal move on occasion?

## Why This Is Asked
Tests ability to combine arrays/linked lists (deques), hash maps, and a heap to maintain a sliding-window top-K efficiently.

## Key Concepts
- Sliding window, expiration, lazy deletions in a heap
- Per-user state via linked-list/deque and running sums
- Time/space trade-offs for real-time top-K

## Code Example
```javascript
class WaveTopK {
  constructor(W) {
    this.W = W;
    this.userMap = new Map(); // user_id -> {queue: [], sum}
    this.heap = new MaxHeap(); // stores [sum, user_id]
  }
  addEvent(userId, score, ts) {
    let entry = this.userMap.get(userId);
    if (!entry) {
      entry = { queue: [], sum: 0 };
      this.userMap.set(userId, entry);
    }
    entry.queue.push([ts, score]);
    entry.sum += score;
    this.heap.push([entry.sum, userId]);
  }
  topK(currentTime, K) {
    const seen = new Map();
    const res = [];
    while (res.length < K && !this.heap.isEmpty()) {
      const [sum, uid] = this.heap.pop();
      const ent = this.userMap.get(uid);
      if (!ent) continue;
      // expire check
      this.expireUser(uid, currentTime);
      if (ent.sum !== sum) {
        this.heap.push([ent.sum, uid]);
        continue;
      }
      res.push(uid);
    }
    // Reinsert popped elements
    for (const uid of res) this.heap.push([this.userMap.get(uid).sum, uid]);
    return res;
  }
  expireUser(userId, currentTime) {
    const ent = this.userMap.get(userId);
    if (!ent) return;
    while (ent.queue.length && ent.queue[0][0] <= currentTime - this.W) {
      const [, val] = ent.queue.shift();
      ent.sum -= val;
    }
  }
}
```

## Follow-up Questions
- How would you handle ties in topK?
- What changes if K is large relative to N?
- How would you adapt for variable window sizes per user?

## Why This Is Asked
This problem tests dynamic programming skills on a directed acyclic graph (DAG) with multiple predecessor choices and path counting for optimal solutions. The ability to handle several predecessors, implement proper tie-breaking for path counting, and correctly apply modulo arithmetic demonstrates code clarity and robustness with edge cases.

## Key Concepts
- DP on DAG with 3-step transitions (i → i+1, i+2, i+3)
- Maintaining both the optimal value and the count of optimal paths
- Modulo arithmetic (1e9+7) for path counting
- Edge-case handling for small n and negative profit values

## Code Example
```javascript
function maxProfitAndPaths(profits) {
  const n = profits.length;
  const MOD = 1000000007n;
  if (n === 0) return { best: 0, cnt: 1 };
  if (n === 1) return { best: profits[0], cnt: 1 };

  const best = new Array(n).fill(0);
  const cnt = new Array(n).fill(0);
  best[0] = profits[0];
  cnt[0] = 1;

  for (let i = 1; i < n; i++) {
    let maxVal = -Infinity;
    for (const p of [i-1, i-2, i-3]) {
      if (p >= 0) {
        const cand = best[p] + profits[i];
        if (cand > maxVal) {
          maxVal = cand;
          cnt[i] = cnt[p];
        } else if (cand === maxVal) {
          cnt[i] = (cnt[i] + cnt[p]) % MOD;
        }
      }
    }
    best[i] = maxVal;
  }
  return { best: best[n-1], cnt: cnt[n-1] };
}
```

## Why This Is Asked
This question tests practical skills in per-prefix top-K maintenance using a Trie with bounded heaps and dynamic frequency updates, revealing trade-offs between speed and memory.

## Key Concepts
- Trie with per-node top-K storage using a min-heap with bounded size K
- Min-heap with tie-breaking by word for stable ordering
- Dynamic frequency updates with addWord(word, delta) supporting negative deltas
- Automatic deletion when frequency reaches zero

## Time and Memory Trade-offs
- **Time Complexity**: addWord runs in O(L × log K) where L is word length, as we traverse the path and perform heap operations. getTopK runs in O(K × log K) for heap extraction plus O(K log K) for sorting.
- **Space Complexity**: O(N × L + N × K) where N is the total number of unique words—the Trie itself costs O(N × L), and each node stores up to K heap entries.
- **Trade-off**: Increasing K improves result quality but increases memory usage and slows updates. A smaller K is faster but returns fewer suggestions.

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.topK = new MinHeap((a, b) => {
      if (a.freq !== b.freq) return a.freq - b.freq;
      return a.word.localeCompare(b.word);
    });
  }
}

class AutocompleteEngine {
  constructor(K = 3) {
    this.root = new TrieNode();
    this.freqMap = new Map();
    this.K = K;
  }

  addWord(word, delta) {
    const newFreq = (this.freqMap.get(word) || 0) + delta;
    if (newFreq <= 0) {
      this.freqMap.delete(word);
    } else {
      this.freqMap.set(word, newFreq);
    }

    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) {
        node.children.set(char, new TrieNode());
      }
      node = node.children.get(char);
      node.topK.upsert({ word, freq: newFreq }, this.K);
    }
  }

  getTopK(prefix, K) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.children.has(char)) return [];
      node = node.children.get(char);
    }
    return node.topK.getTop(K);
  }
}
```

## Why This Is Asked
Tests dynamic dictionary updates with a prefix-based query, combining trie augmentation and edge-case handling. 

## Key Concepts
- Trie with per-node passCount to track subtree content
- O(length of word) updates for insert/delete
- LCP query via prefix traversal until no valid child
- Edge cases: duplicates, deleting absent words, memory pruning

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.cnt = 0;
  }
}
class DynamicDict {
  constructor(){ this.root = new TrieNode(); this.hasWord=new Set(); }
  insert(w){ if(this.hasWord.has(w)) return; this.hasWord.add(w); let node=this.root; for(const ch of w){ if(!node.next.has(ch)) node.next.set(ch,new TrieNode()); node=node.next.get(ch); node.cnt++; } }
  delete(w){ if(!this.hasWord.has(w)) return; this.hasWord.delete(w); let node=this.root; for(const ch of w){ const child=node.next.get(ch); child.cnt--; if(child.cnt===0){ node.next.delete(ch); } node=child; } }
  lcpQuery(q){ let node=this.root, depth=0, res=0; for(const ch of q){ if(!node.next.has(ch)) break; node=node.next.get(ch); depth++; if(node.cnt>0) res=depth; } return res; }
}
```

